DIALOGS = [
[trp_sod_strategy_advisor, "sa_select_general2", [
	(eq, "$g_sod_sa_talk_subject", 22),
	], "The Republic of Marina fought bravely against the Imperial Legion and won many decisive battles.  Their spearmen were particularly deadly against cavalry.  Their main weakness was their speed on the map.  Without cavalry, the Legion would only engage in battles they could win.  After a while the Republic of Marina was outmaneuvered and forced to retreat to their castles where they were starved to death and denied battle.  The Legion has no honor and favors winning at all costs.  If they force you into a corner, do not wait it out, fight like a caged animal.", "sa_select_3", []],
]
